mapper.select:
SELECT COUNT(1)
FROM pcd_directory_closure_table
WHERE user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND ancestor_id = #{ancestorId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND descendant_id = #{descendantId,typeHandler=org.project.util.UUIDBinaryTypeHandler}

SELECT COALESCE(MAX(depth), 0)
FROM pcd_directory_closure_table
WHERE user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND descendant_id = #{nodeId,typeHandler=org.project.util.UUIDBinaryTypeHandler}

SELECT descendant_id
FROM pcd_directory_closure_table
WHERE user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND ancestor_id = #{ancestorId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
ORDER BY depth ASC

mapper.delete:
DELETE c
FROM pcd_directory_closure_table c
JOIN (
SELECT descendant_id
FROM pcd_directory_closure_table
WHERE user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND ancestor_id = #{movingNodeId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
) subtree
ON subtree.descendant_id = c.descendant_id
JOIN (
SELECT ancestor_id
FROM pcd_directory_closure_table
WHERE user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND descendant_id = #{movingNodeId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND ancestor_id != #{movingNodeId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
) old_ancestors
ON old_ancestors.ancestor_id = c.ancestor_id

DELETE c
FROM pcd_directory_closure_table c
JOIN (
SELECT descendant_id
FROM pcd_directory_closure_table
WHERE user_id = #{userId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
AND ancestor_id = #{rootNodeId,typeHandler=org.project.util.UUIDBinaryTypeHandler}
) subtree
ON subtree.descendant_id = c.descendant_id
